// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/{audience}/account/mfa/totp/enroll", wrapper.EnrollTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/{audience}/account/mfa/totp/verify", wrapper.VerifyTotpEnrollment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/{audience}/account/mfa/totp/disable", wrapper.DisableTotp)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/{audience}/account/mfa/recovery-codes/regenerate", wrapper.RegenerateRecoveryCodes)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/{audience}/auth/mfa/complete", wrapper.CompleteMfaLogin)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/{audience}/auth/step-up", wrapper.StepUpAuthentication)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/enterprise/break-glass-sessions", wrapper.ListBreakGlassSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/break-glass-sessions", wrapper.CreateBreakGlassSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/enterprise/break-glass-sessions/{id}/revoke", wrapper.RevokeBreakGlassSession)
	})

	return r
}

